package main

import (
    "fmt"
    "time"
    "github.com/allegro/bigcache/v3"
)

func main() {
    cache, _ := bigcache.NewBigCache(bigcache.DefaultConfig(10 * time.Minute))

    // Store a value
    cache.Set("testkey", []byte("testvalue"))

    // Try to retrieve it
    value, err := cache.Get("testkey")
